function proactive_intelligence_ready(PDO $pdo): bool {
    try{return installer_table_exists($pdo,'cognitive_watches')&&installer_table_exists($pdo,'cognitive_alert_states');}
    catch(Throwable $e){return false;}
}
function proactive_preferences(PDO $pdo,array $viewer): array {
    $defaults=['proactive_notification_mode'=>'important','proactive_briefing_enabled'=>1];
    if(!proactive_intelligence_ready($pdo))return $defaults;
    try{$pdo->prepare('INSERT IGNORE INTO user_preferences(user_id) VALUES(?)')->execute([$viewer['id']]);$q=$pdo->prepare('SELECT proactive_notification_mode,proactive_briefing_enabled FROM user_preferences WHERE user_id=?');$q->execute([$viewer['id']]);$row=$q->fetch()?:[];$mode=(string)($row['proactive_notification_mode']??'important');if(!in_array($mode,['all','important','mentions'],true))$mode='important';return ['proactive_notification_mode'=>$mode,'proactive_briefing_enabled'=>(int)($row['proactive_briefing_enabled']??1)];}catch(Throwable $e){return $defaults;}
}
function proactive_preferences_set(PDO $pdo,array $viewer,string $mode,bool $briefing): array {
    if(!proactive_intelligence_ready($pdo))throw new RuntimeException('Proactive Research Intelligence requires the Phase 17 database upgrade.');
    $mode=strtolower(trim($mode));if(!in_array($mode,['all','important','mentions'],true))throw new InvalidArgumentException('Invalid proactive notification mode.');
    $pdo->prepare('INSERT INTO user_preferences(user_id,proactive_notification_mode,proactive_briefing_enabled) VALUES(?,?,?) ON DUPLICATE KEY UPDATE proactive_notification_mode=VALUES(proactive_notification_mode),proactive_briefing_enabled=VALUES(proactive_briefing_enabled)')->execute([$viewer['id'],$mode,$briefing?1:0]);
    return ['proactive_notification_mode'=>$mode,'proactive_briefing_enabled'=>$briefing?1:0];
}
function proactive_watch_key(string $type,?string $publicId,?string $query): string {$identity=$type==='question'?mb_strtolower(trim((string)$query)):trim((string)$publicId);return hash('sha256',$type.'|'.$identity);}
function proactive_watch_access(PDO $pdo,array $viewer,string $type,?string $publicId,?string $query=null): bool {
    if($type==='question')return mb_strlen(trim((string)$query))>=3&&mb_strlen(trim((string)$query))<=500;
    $publicId=trim((string)$publicId);if($publicId==='')return false;
    if($type==='source')return source_access($pdo,$publicId,$viewer)!==null;
    if($type==='project')return project_access($pdo,(int)$viewer['id'],$publicId)!==null;
    if($type==='entity')return research_entity_access($pdo,$viewer,$publicId)!==null;
    if($type==='claim'){$q=$pdo->prepare('SELECT rp.public_id FROM research_claims rc JOIN research_projects rp ON rp.id=rc.project_id WHERE rc.public_id=? LIMIT 1');$q->execute([$publicId]);$project=(string)($q->fetchColumn()?:'');return $project!==''&&project_access($pdo,(int)$viewer['id'],$project)!==null;}
    return false;
}
function proactive_watch_upsert(PDO $pdo,array $viewer,string $type,?string $publicId=null,?string $query=null,string $alertLevel='important'): array {
    if(!proactive_intelligence_ready($pdo))throw new RuntimeException('Proactive Research Intelligence requires the Phase 17 database upgrade.');
    $type=strtolower(trim($type));if(!in_array($type,['source','project','claim','entity','question'],true))throw new InvalidArgumentException('Invalid watch type.');
    $publicId=$type==='question'?null:trim((string)$publicId);$query=$type==='question'?trim((string)$query):null;if(!proactive_watch_access($pdo,$viewer,$type,$publicId,$query))throw new RuntimeException('That object is unavailable or you do not have access.');
