    $pdo->prepare("INSERT INTO cognitive_watches(public_id,user_id,watch_type,object_public_id,query_text,watch_key,alert_level,status,muted_until) VALUES(?,?,?,?,?,?,?,'active',NULL) ON DUPLICATE KEY UPDATE alert_level=VALUES(alert_level),status='active',muted_until=NULL,updated_at=NOW()")->execute([$public,$viewer['id'],$type,$publicId,$query,$key,$alertLevel]);
    $q=$pdo->prepare('SELECT * FROM cognitive_watches WHERE user_id=? AND watch_key=? LIMIT 1');$q->execute([$viewer['id'],$key]);return $q->fetch()?:[];
}
function proactive_watch_remove(PDO $pdo,array $viewer,string $publicId): bool {if(!proactive_intelligence_ready($pdo))return false;$q=$pdo->prepare('DELETE FROM cognitive_watches WHERE user_id=? AND public_id=?');$q->execute([$viewer['id'],trim($publicId)]);return $q->rowCount()>0;}
function proactive_watch_pause(PDO $pdo,array $viewer,string $publicId,bool $paused): bool {if(!proactive_intelligence_ready($pdo))return false;$q=$pdo->prepare("UPDATE cognitive_watches SET status=?,updated_at=NOW() WHERE user_id=? AND public_id=?");$q->execute([$paused?'paused':'active',$viewer['id'],trim($publicId)]);return $q->rowCount()>0;}
function proactive_watch_list(PDO $pdo,array $viewer): array {if(!proactive_intelligence_ready($pdo))return [];$q=$pdo->prepare("SELECT * FROM cognitive_watches WHERE user_id=? ORDER BY status='active' DESC,updated_at DESC,id DESC LIMIT 200");$q->execute([$viewer['id']]);$out=[];foreach($q->fetchAll() as $row){if($row['watch_type']==='question'||proactive_watch_access($pdo,$viewer,(string)$row['watch_type'],(string)$row['object_public_id'],(string)$row['query_text']))$out[]=$row;}return $out;}
function proactive_feed_items(array $feed): array {$out=[];foreach((array)($feed['sections']??[]) as $section)foreach((array)($section['items']??[]) as $item)$out[]=$item;return $out;}
function proactive_observation_refs(array $item): array {
    $refs=[];$add=function(string $type,string $public)use(&$refs): void {$type=strtolower(trim($type));$public=trim($public);if($public==='')return;if(in_array($type,['research','project'],true))$type='project';if(in_array($type,['source','project','claim','entity','conversation','team'],true))$refs[$type.':'.$public]=['type'=>$type,'public_id'=>$public];};
    foreach((array)($item['actions']??[]) as $action){foreach((array)($action['context']??[]) as $ctx)$add((string)($ctx['type']??''),(string)($ctx['public_id']??''));$href=(string)($action['href']??'');if($href!==''){$parts=parse_url($href);$path=(string)($parts['path']??'');parse_str((string)($parts['query']??''),$params);$id=(string)($params['id']??'');if($id!==''){if($path==='/source.php')$add('source',$id);elseif($path==='/research-project.php')$add('project',$id);elseif($path==='/research-claim.php')$add('claim',$id);elseif($path==='/entity.php')$add('entity',$id);elseif($path==='/team.php')$add('team',$id);}if($path==='/home.php'&&!empty($params['team']))$add('team',(string)$params['team']);if($path==='/home.php'&&!empty($params['agent']))$add('conversation',(string)$params['agent']);}}
