function proactive_observation_watch_target(array $item): ?array {$refs=proactive_observation_refs($item);foreach(['claim','source','entity','project'] as $preferred)foreach($refs as $ref)if($ref['type']===$preferred)return $ref;return null;}
function proactive_question_match(string $query,array $item): bool {$query=mb_strtolower(trim($query));if($query==='')return false;$hay=mb_strtolower(trim((string)($item['title']??'').' '.(string)($item['body']??'')));if(mb_stripos($hay,$query)!==false)return true;$words=array_values(array_filter(preg_split('/\s+/u',$query)?:[],fn($w)=>mb_strlen($w)>=4));if(!$words)return false;$hits=0;foreach($words as $word)if(mb_stripos($hay,$word)!==false)$hits++;return $hits>=min(2,count($words));}
function proactive_matches_watch(array $item,array $watch): bool {if(($watch['status']??'active')!=='active')return false;if(!empty($watch['muted_until'])&&strtotime((string)$watch['muted_until'])>time())return false;if(($watch['watch_type']??'')==='question')return proactive_question_match((string)($watch['query_text']??''),$item);$needle=(string)$watch['watch_type'].':'.(string)$watch['object_public_id'];foreach(proactive_observation_refs($item) as $ref)if($ref['type'].':'.$ref['public_id']===$needle)return true;return false;}
function proactive_is_important(array $item): bool {$type=(string)($item['type']??'');$priority=(string)($item['priority']??'medium');$score=(int)($item['score']??0);return $priority==='high'||$score>=82||in_array($type,['pending_agent_action','research_conflict','related_conflict','source_change'],true);}
function proactive_is_mention(array $item,array $viewer): bool {if(($item['type']??'')==='pending_agent_action')return true;if(($item['type']??'')!=='team_activity')return false;$username=trim((string)($viewer['username']??''));return $username!==''&&mb_stripos((string)($item['body']??''),'@'.$username)!==false;}
function proactive_why_this_matters(array $item,bool $watched=false): string {if($watched)return 'You explicitly watch this Research context, and its current state changed.';return match((string)($item['type']??'')){'pending_agent_action'=>'A Research write is waiting for your explicit confirmation.','research_conflict','related_conflict'=>'Current evidence disagrees and may change a Research conclusion.','source_change'=>'A source used or watched in your Research changed after evidence was captured.','research_gap'=>'A current Claim still has an evidence gap that may need verification.','new_evidence'=>'New evidence was added to Research you can access.','team_activity'=>'New Team activity may affect shared Research.','research_task'=>'Open Research work is waiting to be continued.','related_research'=>'A new evidence relationship connects to active Research.',default=>'Annotated detected a meaningful change in current Research state.'};}
function proactive_context_access(PDO $pdo,array $viewer,array $context): bool {
    foreach((array)($context['refs']??[]) as $ref){$type=(string)($ref['type']??'');$public=(string)($ref['public_id']??'');if($public==='')continue;if($type==='source'&&source_access($pdo,$public,$viewer)===null)return false;if($type==='project'&&project_access($pdo,(int)$viewer['id'],$public)===null)return false;if($type==='entity'&&research_entity_access($pdo,$viewer,$public)===null)return false;if($type==='claim'){$q=$pdo->prepare('SELECT rp.public_id FROM research_claims rc JOIN research_projects rp ON rp.id=rc.project_id WHERE rc.public_id=? LIMIT 1');$q->execute([$public]);$project=(string)($q->fetchColumn()?:'');if($project===''||project_access($pdo,(int)$viewer['id'],$project)===null)return false;}if($type==='conversation'&&function_exists('conversation_access')&&conversation_access($pdo,$viewer,$public)===null)return false;if($type==='team'){$q=$pdo->prepare('SELECT 1 FROM teams t JOIN team_members tm ON tm.team_id=t.id WHERE t.public_id=? AND tm.user_id=? LIMIT 1');$q->execute([$public,$viewer['id']]);if(!$q->fetchColumn())return false;}}return true;
