function proactive_primary_url(array $item): ?string {foreach((array)($item['actions']??[]) as $action)if(($action['type']??'')==='link'){$href=(string)($action['href']??'');if(str_starts_with($href,'/')&&!str_starts_with($href,'//'))return $href;}return null;}
function proactive_should_alert(array $item,array $viewer,array $prefs,array $watches,?array &$matchedWatch=null): bool {foreach($watches as $watch){if(!proactive_matches_watch($item,$watch))continue;if(($watch['alert_level']??'important')==='important'&&!proactive_is_important($item))continue;$matchedWatch=$watch;return true;}$mode=(string)($prefs['proactive_notification_mode']??'important');if($mode==='all')return true;if($mode==='mentions')return proactive_is_mention($item,$viewer);return proactive_is_important($item);}
function proactive_notification_upsert(PDO $pdo,array $viewer,array $item,array $context,string $payloadHash,?array $state): ?string {
    if(!notification_pref_enabled($pdo,(int)$viewer['id'],'research_proactive'))return null;if(notification_is_muted($pdo,(int)$viewer['id'],'research',$context))return null;$body=(string)($item['title']??'Research update');if(trim((string)($item['body']??''))!=='')$body.=' — '.mb_substr(trim((string)$item['body']),0,500);$json=json_encode($context,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);$existing=trim((string)($state['notification_public_id']??''));
    if($existing!==''){$q=$pdo->prepare('SELECT public_id FROM notifications WHERE user_id=? AND public_id=? LIMIT 1');$q->execute([$viewer['id'],$existing]);if($q->fetchColumn()){$pdo->prepare("UPDATE notifications SET notification_type='research_proactive',category='research',body=?,context_json=?,read_at=NULL,archived_at=NULL,created_at=NOW() WHERE user_id=? AND public_id=?")->execute([$body,$json,$viewer['id'],$existing]);return $existing;}}
    $public=ulid_like();$dedupe='proactive:'.(string)$item['key'];try{$pdo->prepare("INSERT INTO notifications(public_id,user_id,actor_user_id,notification_type,category,dedupe_key,group_key,object_type,object_public_id,body,context_json) VALUES(?,?,NULL,'research_proactive','research',?,?, 'cognitive_alert',?,?,?)")->execute([$public,$viewer['id'],$dedupe,$dedupe,(string)$item['key'],$body,$json]);return $public;}catch(PDOException $e){$q=$pdo->prepare('SELECT public_id FROM notifications WHERE user_id=? AND dedupe_key=? LIMIT 1');$q->execute([$viewer['id'],$dedupe]);$found=$q->fetchColumn();return $found!==false?(string)$found:null;}
