function proactive_intelligence_sync(PDO $pdo,array $viewer,?array $feed=null): array {
    if(!proactive_intelligence_ready($pdo))return ['ready'=>false,'evaluated'=>0,'notified'=>0];$feed=$feed??cognitive_feed_compose($pdo,$viewer,null,8,60);$prefs=proactive_preferences($pdo,$viewer);$watches=proactive_watch_list($pdo,$viewer);$evaluated=0;$notified=0;
