 DUPLICATE KEY UPDATE observation_type=VALUES(observation_type),state='active',payload_hash=VALUES(payload_hash),occurrence_count=occurrence_count+1,last_seen_at=NOW(),snoozed_until=NULL,resolved_at=NULL")->execute([$viewer['id'],$key,(string)($item['type']??'observation'),$payloadHash]);$q=$pdo->prepare('SELECT * FROM cognitive_alert_states WHERE user_id=? AND observation_key=? LIMIT 1');$q->execute([$viewer['id'],$key]);$state=$q->fetch()?:[];$notification=proactive_notification_upsert($pdo,$viewer,$item,$context,$payloadHash,$state);if($notification!==null){$pdo->prepare('UPDATE cognitive_alert_states SET notification_public_id=?,last_notified_at=NOW() WHERE user_id=? AND observation_key=?')->execute([$notification,$viewer['id'],$key]);$notified++;}}
    return ['ready'=>true,'evaluated'=>$evaluated,'notified'=>$notified];
